const logger = createLogger("cleanup-archived-job");

/**
 * Deleted workspaces are purged as a unit after the fixed recovery window.
 * Existing issue and activity retention continues for live workspaces.
 */
export async function runCleanupArchivedJob(now: Date): Promise<JobResult> {
  return runJob("cleanup-archived", async (result) => {
    const orgCutoff = toIsoTimestamp(
      new Date(now.getTime() - DELETED_WORKSPACE_RETENTION_DAYS * MS_PER_DAY),
    );
    const expiredOrgIds = await orgRepo.listExpiredArchivedOrgIds(orgCutoff);
    for (const orgId of expiredOrgIds) {
      const db = getDb();
      const tables = [
        projectMembers, issueLabels, attachments, comments, notifications,
        notificationPreferences, activityEvents, invoices, subscriptions,
        webhookDeliveries, webhookEndpoints, searchIndex, labels, issues,
        projects, invitations, members, organizationUsage,
      ] as const;
      for (const table of tables) db.delete(table).where(eq(table.orgId, orgId)).run();
      db.update(sessions).set({ activeOrgId: null }).where(eq(sessions.activeOrgId, orgId)).run();
      db.update(users).set({ activeOrgId: null }).where(eq(users.activeOrgId, orgId)).run();
      db.delete(organizations).where(eq(organizations.id, orgId)).run();
      result.processed += 1;
    }
    const orgIds = await orgRepo.listActiveOrgIds(ORG_BATCH);

    for (const orgId of orgIds) {
      const org = await orgRepo.findOrgById(orgId);
      if (!org || org.archivedAt !== null) continue;

      const { retentionDays } = getPlanLimits(org.plan);
      const cutoff = toIsoTimestamp(
        new Date(now.getTime() - retentionDays * MS_PER_DAY),
      );

      const archived = await issueRepo.listIssues({
        orgId,
        limit: PAGE_SIZE,
        cursor: null,
        includeArchived: true,
      });

      for (const issue of archived.items) {
        if (!isArchived(issue)) continue;
        if (issue.archivedAt === null || issue.archivedAt > cutoff) continue;

        await searchRepo.deleteSearchDocument(orgId, "issue", issue.id);
        result.processed += 1;
      }

      try {
        const purged = await activityRepo.purgeActivityBefore(orgId, cutoff);
        result.processed += purged;
      } catch (error) {
        result.failed += 1;
        logger.error("activity purge failed", {
          orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}
