    .select({ subscription: subscriptions })
    .from(subscriptions)
    .innerJoin(organizations, eq(organizations.id, subscriptions.orgId))
    .where(and(orgPredicate(subscriptions.orgId, orgId), isNull(organizations.archivedAt)))
